import os
import shutil
import zipfile
from unittest.mock import MagicMock

import qai_hub.public_api_pb2 as api_pb
from qai_hub import api_utils, public_rest_api, s3_transfer


def _ctx(value):
    """Wrap a value so it can stand in for a `with`-statement target."""
    cm = MagicMock()
    cm.__enter__.return_value = value
    cm.__exit__.return_value = False
    return cm


def test_upload_file_drives_transfer_manager(monkeypatch, tmp_path):
    credentials = api_pb.S3Credentials(bucket="bkt", key="models/k.bin")
    src = tmp_path / "m.bin"
    src.write_bytes(b"x" * 32)

    monkeypatch.setattr(s3_transfer, "_build_client", lambda c: MagicMock())
    manager = MagicMock()
    future = MagicMock()
    manager.upload.return_value = future
    monkeypatch.setattr(
        s3_transfer, "TransferManager", lambda client, **kwargs: _ctx(manager)
    )

    s3_transfer.upload_file(
        credentials, str(src), verbose=False, progress_bar_description="up"
    )

    args, kwargs = manager.upload.call_args
    assert args[0] == str(src)
    assert args[1] == "bkt"
    assert args[2] == "models/k.bin"
    assert kwargs["extra_args"][
        "ContentType"
    ] == api_utils.guess_file_http_content_type(str(src))
    future.result.assert_called_once()


def test_download_file_moves_object_into_place(monkeypatch, tmp_path):
    credentials = api_pb.S3Credentials(bucket="b", key="k")
    client = MagicMock()
    client.head_object.return_value = {"ContentLength": 4}
    monkeypatch.setattr(s3_transfer, "_build_client", lambda c: client)

    manager = MagicMock()

    def fake_download(bucket, key, dest, subscribers):
        with open(dest, "wb") as f:
            f.write(b"data")
        return MagicMock()

    manager.download.side_effect = fake_download
    monkeypatch.setattr(
        s3_transfer, "TransferManager", lambda client, **kwargs: _ctx(manager)
    )

    dst = tmp_path / "out.bin"
    result = s3_transfer.download_file(credentials, "out.bin", str(dst), verbose=False)

    assert os.path.isfile(result)
    with open(result, "rb") as f:
        assert f.read() == b"data"


def test_download_file_extracts_zip(monkeypatch, tmp_path):
    zip_src = tmp_path / "src.zip"
    with zipfile.ZipFile(zip_src, "w") as z:
        z.writestr("inner/weights.bin", "hello")

    credentials = api_pb.S3Credentials(bucket="b", key="k")
    client = MagicMock()
    client.head_object.return_value = {"ContentLength": zip_src.stat().st_size}
    monkeypatch.setattr(s3_transfer, "_build_client", lambda c: client)

    manager = MagicMock()

    def fake_download(bucket, key, dest, subscribers):
        shutil.copyfile(zip_src, dest)
        return MagicMock()

    manager.download.side_effect = fake_download
    monkeypatch.setattr(
        s3_transfer, "TransferManager", lambda client, **kwargs: _ctx(manager)
    )

    out_dir = tmp_path / "out"
    out_dir.mkdir()
    result = s3_transfer.download_file(
        credentials, "model.zip", str(out_dir), verbose=False, extract_if_zipped=True
    )

    assert os.path.isfile(os.path.join(result, "inner", "weights.bin"))


def test_download_and_extract_model_promotes_single_base_dir(tmp_path):
    # Promotion runs on the already-extracted directory the callback returns
    # (the unzip itself lives in download_file). A zipped directory model must
    # land as dst/<name>/<contents>, matching the pre-signed path.
    extracted = tmp_path / "model"
    (extracted / "inner").mkdir(parents=True)
    (extracted / "inner" / "weights.bin").write_text("w")
    dst = tmp_path / "dst"
    dst.mkdir()

    def download_and_extract_to(target):
        # Stand in for download_file: the object has been downloaded and unzipped.
        return str(extracted)

    result = public_rest_api._download_and_extract_model(
        download_and_extract_to, "model.zip", str(dst), extract_if_zipped=True
    )

    assert os.path.isfile(os.path.join(result, "weights.bin"))


def test_download_and_extract_model_rejects_multiple_base_entries(tmp_path):
    extracted = tmp_path / "model"
    (extracted / "a").mkdir(parents=True)
    (extracted / "b").mkdir(parents=True)
    dst = tmp_path / "dst"
    dst.mkdir()

    import pytest

    def download_and_extract_to(target):
        return str(extracted)

    with pytest.raises(ValueError):
        public_rest_api._download_and_extract_model(
            download_and_extract_to, "model.zip", str(dst), extract_if_zipped=True
        )


def test_download_and_extract_model_returns_download_when_not_zipped(tmp_path):
    f = tmp_path / "m.bin"
    f.write_text("x")

    def download_and_extract_to(target):
        # Stand in for download_file on a non-zip: the object is downloaded to target.
        return target

    result = public_rest_api._download_and_extract_model(
        download_and_extract_to, "m.bin", str(f), extract_if_zipped=False
    )

    assert result == str(f)
